sealed class ServiceProxy : DispatchProxy      // implements IServiceApi at runtime
{
    private IServiceApi _real = default!;

    protected override object? Invoke(MethodInfo method, object?[]? args)
    {
        using var span = Tracer.Start(method.Name);  // policy: tracing
        try { return method.Invoke(_real, args); }   // delegate, same interface
        catch (TargetInvocationException e) { throw e.InnerException!; }
    }
}

