sealed class PolicyHandler : DelegatingHandler
{
    protected override async Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken ct)
    {
        request.Headers.Add("x-correlation-id", Correlation.Current);  // policy
        var response = await base.SendAsync(request, ct);              // delegate
        Metrics.Observe(request.RequestUri, response.StatusCode);
        return response;
    }
}
